import logging
from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.common.common import LocalBasicPage
from taf.selenium.sbts_fsm3.pages import modals


class GraceFullCellShutDownModal(LocalBasicPage):

    _GRACEFUL_SELECTED = ('//div[@class="modal-content"]//'
                          'input[@ng-model="parameters.isGraceful" and contains(@class, "ng-not-empty")]')

    _GRACEFUL = (
        '//div[contains(@class, "modal-dialog")]//*[contains(text(), "Graceful cell shut down")]/parent::label')

    def _select_graceful_shut_down(self, with_graceful, timeout):
        if with_graceful and not self.element_exists(self._GRACEFUL_SELECTED):
            logging.info("input with_graceful={}, and gracefull is not selected, click the graceful".format(with_graceful))
            self.click_enabled_element((By.XPATH, self._GRACEFUL), timeout)
        elif not with_graceful and self.element_exists(self._GRACEFUL_SELECTED):
            logging.info("input with_graceful={}, and gracefull is selected, click the graceful".format(with_graceful))
            self.click_enabled_element((By.XPATH, self._GRACEFUL), timeout)
        else:
            logging.info("not change the default graceful status")


class ResetModalCommonOperation(modals.ResetModalCommonOperation, GraceFullCellShutDownModal):

    def _confirm_reset_modal(self, with_graceful, without_radio_reset, timeout):
        reset_modal = modals.ResetModal(self.driver)
        reset_modal.wait_until_reset_modal_appear()

        self._select_graceful_shut_down(with_graceful, timeout)

        self._select_without_radio_reset(without_radio_reset, timeout)
        reset_modal.confirm()


class PowerResetModal(modals.PowerResetModal, GraceFullCellShutDownModal):

    _GRACEFUL_SELECTED = '//span[@class="p-checkbox-icon pi pi-check"]'

    def execute(self, with_graceful=False, timeout=60):
        self._select_graceful_shut_down(with_graceful, timeout)
        self.click_enabled_element((By.XPATH, self._EXECUTE), timeout)


class BlockCellModal(modals.BlockCellModal, GraceFullCellShutDownModal):

    def reset(self, with_graceful=False, timeout=60):
        self._select_graceful_shut_down(with_graceful, timeout)
        self.click_enabled_element((By.XPATH, self._RESET_BUTTON_XPATH), timeout)


class ResetNrOrLte(modals.ResetNrOrLte, GraceFullCellShutDownModal):

    def reset(self, with_graceful=False, timeout=60, with_hard=False):
        self._select_graceful_shut_down(with_graceful, timeout)

        if with_hard:
            self.click_enabled_element((By.XPATH, self._HARD_RESET_BUTTON), timeout)
        else:
            self.click_enabled_element((By.XPATH, self._RESET_BUTTON), timeout)
